import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易要义","description":"周易要义 - 周易要义","frontmatter":{"title":"周易要义","description":"周易要义 - 周易要义"},"headers":[],"relativePath":"zh/classics/yaoyi/001.md","filePath":"zh/classics/yaoyi/001.md"}'),r={name:"zh/classics/yaoyi/001.md"};function i(o,p,c,_,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="周易要义" tabindex="-1">周易要义 <a class="header-anchor" href="#周易要义" aria-label="Permalink to “周易要义”">​</a></h1><p>华父师敬，子 李燔宇， 其学传紫阳。紫阳注周易，独称卜筮，方举占意，有谓恐人涉荒唐。 朱子作本义，首列筮仪，每卦明著象占，使人知观象玩辞，而不涉于谶纬。 魏乃宗正义，删繁取其臧。释文考陆氏，兼引马 融、 郑 康成、 王 肃， 简以得其要约而颇致详。彝尊尚弗知。 朱彝尊经义考未载此书。 希宝诚吉光，开宗辟虚元，孔门教用彰。 其原序云：「传易者更桐祖述惟魏世王辅嗣之注独冠古今，江左诸儒并传其学，其江南义疏十有余家，皆辞尚虚元，乃义涉于释氏，非为教于孔门也。」 三易明周称，盖谓取岐京 叶。 乾健具四德，坤顺惟随倡。弗牛而曰马，牝马行无疆。 此书解「利牝马之贞」，谓坤是阴道，假借柔顺之象，以明柔顺之德。且谓不云牛而云马者，牛虽柔顺，不能行地无疆。 然予更思之，仍即一乾刚， 坤之牝马，正承乾为马而言。盖马乃纯阳，而在坤则为牝马，故轧直曰「利贞」，而坤云「利牝马之贞」，则坤之四德，一乾之四德，仍是以顺为吉。 乾坤分 去声 既定，余卦推类明 叶。 大端弗失正，十翼臣之良。出处益卓然，正色立朝纲，岂徒托空言。用易诚有常，四库广搜罗，懋柱出珍藏。钞刻俾归之，牖世文教昌。卷首题「五言用贲世守长」。</p><p>钦定四库全书经部一</p><p>易类提要：</p><p>臣 等谨案：</p><p>周易要义十卷，宋魏了翁□。了翁字华夫，号鹤山，临邛人。庆元五年进士，官至资政殿大学士、参知政事、佥书枢密院事。事迹具宋史本传。了翁以说经者但知诵习成言，不能求之详博，因取诸经注疏之文，据事别类而录之，谓之九经要义，此其中之第一部也。方回桐江集有周易集义跋，载了翁尝言：「辞变象占，易之纲领，而繇□象爻之辞，画爻位虚之别，互反飞伏之说，乘承比应之例，有不知则义理阙焉。」盖其大旨主于以象数求义理，折衷于汉学、宋学之间，故是编所录，虽主于注疏释文，而采掇谨严，别裁精审，可谓剪除枝蔓，独撷英华。王祎杂说云：孔颖达作九经正义，往往援引纬书之说，欧阳公常欲删而去之，其言不果行。迨鹤山魏氏作要义，始加点削，而其言绝焉，则亦甚与以廓清之功矣。明万历中张萱重编内阁书目，载九经要义，尚存仪礼七册、礼记三册、周易二册、尚书一册、春秋二册、论语二册、孟子二册，又类目六卷本共为一编。今诸经或存或佚，不能复合，故以以世有传本者各著于录。朱□尊经义考群经类中载九经要义二百六十三卷，注曰「分见各经」。然各经皆载要义，而易类则但据宋志载了翁周易集义六十四卷，不载此书，似乎即以集义为要义。考方回周易集义跋曰：鹤山先生谪靖州，取诸经注疏摘为要义，又取濂洛以来诸大儒易说为周易集义。则为二书审矣。乾隆四十二年二月恭校上。总纂官 臣 纪昀、 臣 陆锡熊、 臣 孙士毅，总校官 臣 陆费墀。</p><p>纲领 上六经正义表：</p><p>「臣无忌等言，故祭酒上护军曲阜县开国子孔颖达，宏才硕学，名振当时。贞观年中，奉诏修撰，虽加讨核，尚有未周，爰降丝纶，更令刊定。」𠡠太尉扬州都督监修国史上柱国赵国公臣无忌，司马上柱国英国公臣𪟝、尚书左仆射兼太子少师监修国史上柱国燕国公臣志宁，尚书左仆射兼太子少傅监修国史上护军北平县开国公臣行成，光禄大夫侍中兼太子少保监修国史上护军蓚县开国公臣季辅，光禄大夫吏部尚书监修国史上柱国河南郡开国公臣褚遂良，银青光禄大夫守中书令、监修国史、上骑都尉臣柳奭，前谏议大夫、弘文馆学士臣谷那律，国子博士、弘文馆学士臣伯庄，朝议大夫、国子博士臣王德韶，朝散大夫、行太学博士臣贾公彦，朝散大夫、行太学博士、弘文馆直学士臣范义𫖳，朝散大夫、行太常博士臣柳宣，通直郎、守太学博士臣齐威，宣德郎、守国子助教臣史士弘，宣德郎、守太常博士臣孔志约，右内率府长史、弘文馆直学士臣薛伯珍，兼太学助教臣郑祖玄，征事郎、守太学助教臣随德素，征事郎、守四门博士臣赵君赞，承务郎、守太学助教臣周玄达，承务郎、守四门助教臣李玄植，儒林郎、守四门助教臣王真儒等，上禀宸旨，傍摭群书，谨以上闻，伏增战越。谨言。永徽四年二月二十四日。</p><p>二汉祖述，江南虚玄，惟王辅嗣独冠。传易者，西都则有丁、孟、京、田，东都则有荀、刘、马、郑，大体更相祖述，非有绝伦。唯魏世王辅嗣之注，独冠古今，所以江左诸儒并传其学，河北学者罕能及之。其江南义疏十有余家，皆辞尚虚玄，义多浮诞。原夫易理难穷，虽复玄之又玄，至于垂范作则，便是有而教有。若论住内住外之空，就能就所之说，斯乃义涉于释氏，非为教于孔门也。</p><p>王氏「七日来复」，即易纬六日七分之成数。至若复卦云「七日来复」，并解云：「七日当为七月，谓阳气从五月建午而消，至十一月建子始复，所历七辰，故云七月。」今案辅嗣注云：「阳气始剥尽至来复时凡七日。」则是阳气剥尽之后，凡经七日始复。但阳气虽建午始消，至建戌之月阳气犹在，何得称七月来复？故郑康成引易纬之说，建戌之月，以阳气既尽，建亥之月纯阴用事，至建子之月阳气始生，隔此纯阴一卦，卦主六日七分，举其成数言之，而云「七日来复」。仲尼之纬分明，辅嗣之注若此。康成之说，遗迹可寻。辅嗣注之于前，诸儒背之于后，考其义理，其可通乎？</p><p>先甲先庚，王、郑异义。</p><p>蛊卦云：「先甲三日，后甲三日。」辅嗣注云：「甲者，创制之令，又若汉世之时甲令、乙令也。」辅嗣又云：「令洽乃诛，故后之三日。」又巽卦云：「先庚三日，后庚三日。」辅嗣注云：「申命令谓之庚。」辅嗣又云：「甲、庚，皆申命之谓也。」诸儒同于郑氏之说，以为甲者宣令之日，先之三日而用辛也，欲取改新之义；后之三日而用丁也，取其丁宁之义。王氏注意本不如此，而又不顾其注，妄作异端，进疏解姓名。</p><p>谨与朝散大夫行太学博士臣马嘉运、守太学助教臣赵乾叶等对共参议，详其可否。至十六年，又奉𠡠与前修疏人及给事郎守四门博士上骑都尉苏德融等对𠡠使赵弘智覆更详审，为之注疏，解经凡十卷。「易」一名而含三义。夫「易」者，变化之总名，改换之殊称。圣人初画八卦，设刚柔两画，象二气也；布以三位，象三才也。谓之为「易」，取变化之义。既义总变化，而独以「易」为名者，易纬乾凿度云：「易一名而含三义，所谓易也、变易也、不易也。」又云：「易者，其德也。」郑玄依此义作赞，及易论云：「易一名而含三义：易简，一也；变易二也；不易三也。」崔觐、刘贞简等并用此义，云：「易者，谓生生之德，有易简之义；不易者，言天地定位，不可相易；变易者，谓生生之道，变而相续。」皆以纬称「不烦不扰，澹泊不失」，此明是易简之义，无为之道。故易者，易也，作难易之音。而周简子云：「易者，易 音亦。 也，不易也，变易也。易者，易代之名，凡有无相代，彼此相易，皆是易义。不易者，常体之名，有常有体，无常无体，是不易之义。变易者，相变改之名，两有相变，此为变易。」张氏、何氏并用此义，云：「易者，换代之名，待夺之义。」</p><p>重卦有四说，当从王氏，以伏牺为正。</p><p>孔安国、马融、王肃、姚信等并云伏牺得河图而作易，是则伏牺虽得河图，复须仰观俯察，以相参正，然后画卦。伏牺初画八卦，万物之象皆在其中，故系辞曰</p><p>「八卦成列，象在其中矣」是也。虽有万物之象，其万物变通之理，犹自未备，故因其八卦而更重之，卦有六爻，遂重为六十四卦也。系辞曰「因而重之，爻在其中矣」是也。然重卦之人，诸儒不同，凡有四说：王辅嗣等以为伏牺重卦，郑玄之徒以为神农重卦，孙盛以为夏禹重卦，史迁等以为文王重卦。其言夏禹及文王重卦者，案系辞，神农之时已有盖取诸益与噬嗑。以此论之，不攻自破。其言神农重卦，亦未为得。今以诸文验之。案说卦云：</p><p>「昔者圣人之作易也，幽赞于神明而生□。」凡言作者，创造之谓也。神农以后，便是述修，不可谓之作也。则幽赞用蓍，谓伏牺矣。故乾凿度云：「垂皇策者牺。」上系论用蓍云：「四营而成易，十有八变而成卦。」既言圣人作易，十八变成卦，明用□在六爻之后，非三画之时。伏牺用□，即伏牺已重卦矣。说卦又云：</p><p>「昔者圣人之作易也，将以顺性命之理，是以立天之道曰阴与阳，立地之道曰柔与刚，立人之道曰仁与义。兼三才而两之，故易六画而成卦。」既言「圣人作易」，「兼三才而两之」，又非神农始重卦矣。又上系云：「易有圣人之道四焉：以言者尚其辞，以动者尚其变，以制器者尚其象，以卜筮者尚其占。」此四者之事，皆在六爻之后，何者？三画之时，未有彖繇，不得有「尚其辞」，因而重之，始有变动，三画不动，不得有「尚其变」。揲□布爻，方用之卜筮，□起六爻之后，三画不得有「尚其占」，自然中间「以制器者尚其象」，亦非三画之时。今伏牺结绳而为罔罟，则是制器，明伏牺已重卦矣。又周礼小史掌三皇五帝之书。明三皇已有书也。下系云：「上古结绳而治，后世圣人易之以书契，盖取诸夬。」既象夬卦而造书契，伏牺有书契，则有夬卦矣。故孔安国书序云：「古者伏牺氏之王天下也，始画八卦，造书契，以代结绳之政。」又曰：「伏牺、神农、黄帝之书，谓之三坟是也。」又八卦小成，爻象未备，重三成六，能事毕矣。若言重卦起自神农，其为功也，岂比系辞而已哉？何因易纬等数所历三圣，但云伏牺、文王、孔子，竟不及神农？明神农但有盖取诸益，不重卦矣。故今依王辅嗣，以伏牺既画八卦，即自重为六十四卦，为得其实。其重卦之意，备在说卦。</p><p>连山、归藏，代号周易，亦取岐阳名。</p><p>案周礼太卜三易云：「一曰连山，二曰归藏，三曰周易。」杜子春云：「连山，伏牺；归藏，黄帝。」郑玄易赞及易论云：「夏曰连山，殷曰归藏，周曰周易。」郑玄又释云：「连山者，象山之出云，连连不绝；归藏者，万物莫不归藏于其中；周易者，言易道周普，无所不备。」郑玄虽有此释，更无所据之文，先儒因此遂为文质之义，皆烦而无用，今所不取。案世谱等群书，神农一曰连山氏，亦曰烈山氏；黄帝一曰归藏氏。既连山、归藏并是代号，则周易称周，取□阳地名，毛诗云「周原脢脢」是也。又文王作易之时，正在羑里，周德未兴，犹是殷世也，故题周别于殷。以此文王所演，故谓之周易，其犹周书、周礼题周以别余代，故易纬云「因代以题周」是也。先儒又兼取郑说，云既指周代之名，亦是普徧之义，虽欲无所遐弃，亦恐未可尽通。其易题周，因代以称周，是先儒更不别解。唯皇甫谧云：「文王在羑里，演六十四卦，著七八九六之爻，谓之周易。」以此文王安「周」字。一说卦、爻辞皆文王，一说爻辞周公。</p><p>其周易系辞凡有二说：一说所以卦辞、爻辞并是文王所作。知者，案系辞云：「易之兴也，其于中古乎？作易者其有忧患乎？」又曰：「易之兴也，其当殷之末世，周之盛德邪？当文王与纣之事邪？」又乾凿度云：「垂皇策者牺，卦道演德者文，成命者孔。」通卦验又云：「苍牙通灵，昌之成，孔演命，明道经。」准此诸文，伏牺制卦，文王系辞，孔子作十翼，易历三圣，只谓此也。故史迁云「文王囚而演易」，即是「作易者其有忧患乎」？郑学之徒，并依此说也。二以为验爻辞多是文王后事。案升卦六四：「王用享于岐山。」武王克殷之始，追号文王为王。若爻辞是文王所制，不应云王用亨于岐山。又明夷六五：「箕子之明夷。」武王观兵之后，箕子始被囚奴，文王不宜豫言「箕子之明夷」。又既济九五：「东邻杀牛，不如西邻之礿祭。」说者皆云西邻谓文王，东邻谓纣。文王之时，纣尚南面，岂容自言己德，受福胜殷，又欲抗君之国，遂言东西相邻而已？又左传：「韩宣子适鲁，见易象云：吾乃知周公之德。周公被流言之谤，亦得为忧患也。」验此诸说，以为卦辞文王，爻辞周公。马融、陆绩等并同此说，今依而用之。所以只言三圣，不数周公者，以父统子业故也。</p><p>上下二篇，文王所定。</p><p>案乾凿度云：「孔子曰：阳三阴四，位之正也。故易卦六十四，分为上下，而象阴阳也。夫阳道纯而奇，故上篇三十，所以象阳也。阴道不纯而偶，故下篇三十四，所以法阴也。乾坤者，阴阳之本始，万物之祖宗，故为上篇之始而尊之也。离为日，坎为月，日月之道，阴阳之经，所以始终万物，故以坎离为上篇之终也。咸恒者，男女之始，夫妇之道也。」「人道之兴，必由夫妇，所以奉承祖宗，为天地之主，故为下篇之始而贵之也。既济、未济为最终者，所以明戒慎而全王道也。」以此言之，则上下二篇，文王所定，夫子作纬以释其义也。</p><p>郑学随经分彖、象，通为十翼，</p><p>其彖、象等十翼之辞，以为孔子所作，先儒更无异论。但数十翼亦有多家，既文王易经本分为上下二篇，则区域各别，彖、象释卦，亦当随经而分，故一家数十翼云：上彖一、下彖二、上象三、下象四、上系五、下系六、文言七、说卦八、序卦九、杂卦十。郑学之徒，并同此说，故今亦依之。</p><p>自商瞿至汉晋，传易不绝</p><p>孔子既作十翼，易道大明，自商瞿已后，传授不绝。案儒林传云：商瞿子木本受易于孔子，以授鲁桥庇子庸，子庸授江东𫘛臂子弓，子弓授燕周丑子家，子家授东武孙虞子乘，子乘授齐田何子庄。及秦燔书，易为卜筮之书，独得不禁，故传授者不绝。汉兴，田何授东武王同子中，及雒阳周王孙、梁人丁宽、齐服生，皆著易传数篇。同授菑川杨何字叔元，叔元传京房，京房传梁丘贺，贺授子临，临授御史大夫王骏。其后丁宽又别授田王孙，孙授施犨，犨授张禹，禹授彭宣。此前汉大略传授之人也。其后汉则有马融、荀爽、郑玄、刘表、虞翻、陆绩等及王辅嗣也。</p><p>孟喜前已题「上下经」字，纬文鄙伪</p><p>但子夏传云：虽分为上下二篇，未有经字。经字是后人所加，不知起自谁始。案前汉孟喜易本云「分上下二经」，是孟喜之前已题「经」字。孝经纬称：易建八卦，序六十四卦，转成三百八十四爻，运机布度，其气转易，故称经也。但纬文鄙伪，不可全信。</p>',29)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
